// seed: tests/seed.user.spec.ts · прод, только чтение: кнопки WhatsApp не нажимаются, читается href.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, readSellerMessages, expectSellerMessage, WWW } from './whatsapp.helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('WhatsApp למוכר — готовое сообщение продавцу', () => {
  for (const path of ['/', '/search']) {
    test(`Карточки ${path}: «לצפייה במודעה» без эмодзи + короткая ссылка www на эту карточку #e8bbad #1d8184 #1d84d2 @android @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await page.goto(WWW + path);
      const messages = await readSellerMessages(page);
      expect(messages.length, 'есть сообщения продавцу').toBeGreaterThan(0);
      for (const m of messages) expectSellerMessage(m, WWW + path);
    });
  }
});
